import{_ as e,o as t,c as d,a4 as n}from"./chunks/framework.vNSRaLQv.js";const b=JSON.parse('{"title":"One API Android APK 方案完整文档","description":"","frontmatter":{"title":"One API Android APK 方案完整文档","date":"2026-06-29T00:00:00.000Z"},"headers":[],"relativePath":"posts/Android-Linux折腾记录2.md","filePath":"posts/Android-Linux折腾记录2.md"}'),s={name:"posts/Android-Linux折腾记录2.md"};function i(o,a,l,r,p,c){return t(),d("div",null,[...a[0]||(a[0]=[n(`<h1 id="one-api-android-apk-方案完整文档" tabindex="-1">One API Android APK 方案完整文档 <a class="header-anchor" href="#one-api-android-apk-方案完整文档" aria-label="Permalink to &quot;One API Android APK 方案完整文档&quot;">​</a></h1><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  OneAPI Runner (Android APK)                      │</span></span>
<span class="line"><span>│                                                    │</span></span>
<span class="line"><span>│  ┌───────────────┐   SharedPrefs    ┌────────────┐ │</span></span>
<span class="line"><span>│  │ MainActivity   │ ───存/读配置───▶ │ OneApiSvc  │ │</span></span>
<span class="line"><span>│  │ (原生配置界面)  │ ◀──状态/日志───  │ (前台服务)  │ │</span></span>
<span class="line"><span>│  │                │                  │            │ │</span></span>
<span class="line"><span>│  │ · 端口输入      │                  │ 1. 写resolv│ │</span></span>
<span class="line"><span>│  │ · DNS输入       │                  │ 2. LD_PRE  │ │</span></span>
<span class="line"><span>│  │ · 启停按钮      │                  │ 3. spawn   │ │</span></span>
<span class="line"><span>│  │ · 日志滚动      │                  │ 4. destroy │ │</span></span>
<span class="line"><span>│  │ · 管理后台按钮  │                  │            │ │</span></span>
<span class="line"><span>│  └───────────────┘                  └─────┬──────┘ │</span></span>
<span class="line"><span>│                                          │        │</span></span>
<span class="line"><span>│  ┌───────────────┐                  ┌────▼──────┐ │</span></span>
<span class="line"><span>│  │ WebViewActiv. │◀───http───      │liboneapi.so│ │</span></span>
<span class="line"><span>│  │ (管理后台)     │   127.0.0.1:3k  │(Go二进制)   │ │</span></span>
<span class="line"><span>│  │ :3000         │                  │+LD_PRELOAD │ │</span></span>
<span class="line"><span>│  └───────────────┘                  └───────────┘ │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="核心技术问题与解决方案" tabindex="-1">核心技术问题与解决方案 <a class="header-anchor" href="#核心技术问题与解决方案" aria-label="Permalink to &quot;核心技术问题与解决方案&quot;">​</a></h2><h3 id="问题-android-子进程无法解析-dns" tabindex="-1">问题：Android 子进程无法解析 DNS <a class="header-anchor" href="#问题-android-子进程无法解析-dns" aria-label="Permalink to &quot;问题：Android 子进程无法解析 DNS&quot;">​</a></h3><p>Android 原生二进制（通过 <code>ProcessBuilder</code> 启动）的 DNS 问题：</p><ul><li>Android DNS 走 Binder → netd，子进程没有正确的 Binder context</li><li>Go 内置解析器读 <code>/etc/resolv.conf</code> → Android 上没有 / 指向 <code>[::1]:53</code>（不可达）</li></ul><h4 id="解决方案-ld-preload-custom-resolv-conf" tabindex="-1">解决方案：LD_PRELOAD + CUSTOM_RESOLV_CONF <a class="header-anchor" href="#解决方案-ld-preload-custom-resolv-conf" aria-label="Permalink to &quot;解决方案：LD_PRELOAD + CUSTOM_RESOLV_CONF&quot;">​</a></h4><ol><li><strong>Java 层写自定义 resolv.conf</strong> 到 <code>filesDir/resolv.conf</code></li><li><strong>NDK 编译 libdns_hook.so</strong> 拦截 <code>open(&quot;/etc/resolv.conf&quot;)</code> → 重定向到自定义文件</li><li><strong>Go 用内置解析器</strong>（<code>GODEBUG=netdns=go=1</code>），读到的就是自定义 DNS</li></ol><h3 id="问题-go-交叉编译到-android" tabindex="-1">问题：Go 交叉编译到 Android <a class="header-anchor" href="#问题-go-交叉编译到-android" aria-label="Permalink to &quot;问题：Go 交叉编译到 Android&quot;">​</a></h3><p>关键参数：</p><ul><li><code>CC=aarch64-linux-android31-clang</code> (NDK r27c)</li><li><code>CGO_ENABLED=1</code> (需要 SQLite, 不能用纯 Go SQLite stub)</li><li><code>GOOS=android GOARCH=arm64</code></li><li><code>-tags &#39;osusergo&#39;</code> (不用 <code>netgo</code>，否则 DNS 无法切换)</li><li><code>-buildmode=pie</code> (Android 5.0+ 必须 PIE)</li><li><code>-ldflags &#39;-s -w -extldflags &quot;-Wl,-z,max-page-size=4096&quot;&#39;</code> (去符号 + 优化对齐)</li></ul><p>TLS alignment bug: ARM64 Bionic 要求 p_align=64，Go 编译出来的可能是 8，需用 <code>align_fix.py</code> 修补。</p><h2 id="文件清单" tabindex="-1">文件清单 <a class="header-anchor" href="#文件清单" aria-label="Permalink to &quot;文件清单&quot;">​</a></h2><h3 id="android-项目-oneapi-apk" tabindex="-1">Android 项目 (<code>oneapi-apk/</code>) <a class="header-anchor" href="#android-项目-oneapi-apk" aria-label="Permalink to &quot;Android 项目 (\`oneapi-apk/\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>build.gradle</code></td><td>项目级 AGP 8.9.1 配置</td></tr><tr><td><code>app/build.gradle</code></td><td>模块级构建 + NDK CMake 配置</td></tr><tr><td><code>app/src/main/AndroidManifest.xml</code></td><td>权限 + Activity/Service 声明</td></tr><tr><td><code>app/src/main/java/.../MainActivity.java</code></td><td>原生配置界面 (端口, DNS, 启停, 日志)</td></tr><tr><td><code>app/src/main/java/.../OneApiService.java</code></td><td>前台服务, 管理 Go 进程生命周期</td></tr><tr><td><code>app/src/main/java/.../WebViewActivity.java</code></td><td>WebView 加载管理后台 127.0.0.1:3000</td></tr><tr><td><code>app/src/main/res/layout/activity_main.xml</code></td><td>主界面布局</td></tr><tr><td><code>app/src/main/res/layout/activity_webview.xml</code></td><td>WebView 布局</td></tr><tr><td><code>app/src/main/res/values/themes.xml</code></td><td>AppTheme (AppCompat.Light.NoActionBar)</td></tr><tr><td><code>app/src/main/cpp/dns_hook.c</code></td><td>LD_PRELOAD 库: 拦截 /etc/resolv.conf</td></tr><tr><td><code>app/src/main/cpp/CMakeLists.txt</code></td><td>NDK CMake 构建配置</td></tr><tr><td><code>app/src/main/jniLibs/arm64-v8a/liboneapi.so</code></td><td>交叉编译的 One API 二进制</td></tr><tr><td><code>app/src/main/assets/cl100k_base.tiktoken</code></td><td>tiktoken tokenizer 缓存文件</td></tr><tr><td><code>align_fix.py</code></td><td>修补 ELF PT_TLS alignment 8→64</td></tr></tbody></table><h3 id="go-项目-one-api" tabindex="-1">Go 项目 (<code>one-api/</code>) <a class="header-anchor" href="#go-项目-one-api" aria-label="Permalink to &quot;Go 项目 (\`one-api/\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件/目录</th><th>作用</th></tr></thead><tbody><tr><td><code>main.go</code></td><td>入口, <code>//go:embed web/build/*</code> 嵌入前端</td></tr><tr><td><code>router/web.go</code></td><td>前端静态文件路由</td></tr><tr><td><code>relay/adaptor/openai/token.go</code></td><td>Token encoder 初始化</td></tr><tr><td><code>web/default/</code></td><td>React 前端源码</td></tr><tr><td><code>web/build/default/</code></td><td>React 构建产物 (Go embed 包含)</td></tr></tbody></table><h2 id="构建步骤" tabindex="-1">构建步骤 <a class="header-anchor" href="#构建步骤" aria-label="Permalink to &quot;构建步骤&quot;">​</a></h2><h3 id="_1-编译前端" tabindex="-1">1. 编译前端 <a class="header-anchor" href="#_1-编译前端" aria-label="Permalink to &quot;1. 编译前端&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>cd &lt;one-api&gt;/web/default</span></span>
<span class="line"><span>npm install</span></span>
<span class="line"><span>$env:DISABLE_ESLINT_PLUGIN = &quot;true&quot;</span></span>
<span class="line"><span>npm run build</span></span>
<span class="line"><span>Move-Item build ../build/default</span></span></code></pre></div><h3 id="_2-交叉编译-go-二进制" tabindex="-1">2. 交叉编译 Go 二进制 <a class="header-anchor" href="#_2-交叉编译-go-二进制" aria-label="Permalink to &quot;2. 交叉编译 Go 二进制&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>$env:CC = &quot;&lt;NDK&gt;/toolchains/llvm/prebuilt/windows-x86_64/bin/aarch64-linux-android31-clang.cmd&quot;</span></span>
<span class="line"><span>$env:CGO_ENABLED = &quot;1&quot;</span></span>
<span class="line"><span>$env:GOOS = &quot;android&quot;</span></span>
<span class="line"><span>$env:GOARCH = &quot;arm64&quot;</span></span>
<span class="line"><span>cd &lt;one-api&gt;</span></span>
<span class="line"><span>go build -tags &#39;osusergo&#39; -buildmode=pie \`</span></span>
<span class="line"><span>  -ldflags &#39;-s -w -extldflags &quot;-Wl,-z,max-page-size=4096&quot;&#39; \`</span></span>
<span class="line"><span>  -o ../one-api-android</span></span></code></pre></div><h3 id="_3-修补-tls-alignment" tabindex="-1">3. 修补 TLS alignment <a class="header-anchor" href="#_3-修补-tls-alignment" aria-label="Permalink to &quot;3. 修补 TLS alignment&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>python align_fix.py ../one-api-android</span></span></code></pre></div><h3 id="_4-复制到-apk-项目" tabindex="-1">4. 复制到 APK 项目 <a class="header-anchor" href="#_4-复制到-apk-项目" aria-label="Permalink to &quot;4. 复制到 APK 项目&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Copy-Item ../one-api-android oneapi-apk/app/src/main/jniLibs/arm64-v8a/liboneapi.so -Force</span></span></code></pre></div><h3 id="_5-构建-apk" tabindex="-1">5. 构建 APK <a class="header-anchor" href="#_5-构建-apk" aria-label="Permalink to &quot;5. 构建 APK&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>cd oneapi-apk</span></span>
<span class="line"><span>.\\gradlew.bat assembleDebug</span></span></code></pre></div><h3 id="_6-安装" tabindex="-1">6. 安装 <a class="header-anchor" href="#_6-安装" aria-label="Permalink to &quot;6. 安装&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>adb uninstall com.example.oneapi</span></span>
<span class="line"><span>adb install OneAPI.apk</span></span></code></pre></div><h2 id="关键环境变量-传给-go-进程" tabindex="-1">关键环境变量 (传给 Go 进程) <a class="header-anchor" href="#关键环境变量-传给-go-进程" aria-label="Permalink to &quot;关键环境变量 (传给 Go 进程)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>值</th><th>作用</th></tr></thead><tbody><tr><td><code>TIKTOKEN_CACHE_DIR</code></td><td><code>{workDir}/tiktoken</code></td><td>Tokenizer 缓存目录</td></tr><tr><td><code>GODEBUG</code></td><td><code>netdns=go=1</code></td><td>强制 Go 内置 DNS 解析器</td></tr><tr><td><code>CUSTOM_RESOLV_CONF</code></td><td><code>{workDir}/resolv.conf</code></td><td>自定义 resolv.conf 路径 (给 LD_PRELOAD)</td></tr><tr><td><code>LD_PRELOAD</code></td><td><code>{libDir}/libdns_hook.so</code></td><td>注入 DNS 重定向库</td></tr></tbody></table><h2 id="android-版本兼容性" tabindex="-1">Android 版本兼容性 <a class="header-anchor" href="#android-版本兼容性" aria-label="Permalink to &quot;Android 版本兼容性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>最低版本</th><th>说明</th></tr></thead><tbody><tr><td><strong>APK (Java)</strong></td><td>Android 9 (API 28)</td><td><code>minSdk 28</code>, Gradle 编译限制</td></tr><tr><td><strong>Go 二进制</strong></td><td>Android 12 (API 31)</td><td>NDK 编译器 <code>aarch64-linux-android31-clang</code>, 链接 API 31+ Bionic</td></tr><tr><td><strong>ARM64</strong></td><td>Android 5.0+ (API 21+)</td><td>仅支持 arm64-v8a</td></tr><tr><td><strong>PIE</strong></td><td>Android 5.0+ (API 21+)</td><td><code>-buildmode=pie</code> 强制要求</td></tr></tbody></table><h3 id="实际支持-android-12-api-31-arm64-v8a" tabindex="-1">实际支持: Android 12+ (API 31), arm64-v8a <a class="header-anchor" href="#实际支持-android-12-api-31-arm64-v8a" aria-label="Permalink to &quot;实际支持: Android 12+ (API 31), arm64-v8a&quot;">​</a></h3><p>如果想支持更低版本 (Android 9~11):</p><ul><li>将编译器改为 <code>aarch64-linux-android28-clang</code></li><li>NDK 目录下有 <code>aarch64-linux-android{21,24,26,28,29,30,31,32,33,34,35}-clang</code></li><li>数字越低, 兼容版本越老, 但可能缺失较新的 libc 符号</li></ul><h3 id="硬件要求" tabindex="-1">硬件要求 <a class="header-anchor" href="#硬件要求" aria-label="Permalink to &quot;硬件要求&quot;">​</a></h3><ul><li>CPU: ARM64 (arm64-v8a), 不支持 32 位 ARM</li><li>RAM: 至少 256MB (One API 约占用 80~150MB)</li><li>存储: APK 约 35MB, 运行时额外 ~80MB (SQLite 数据库)</li></ul><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><ol><li>安装 APK, 打开 &quot;OneAPI Runner&quot;</li><li>配置端口 (默认 3000) 和 DNS 服务器 (默认 8.8.8.8,8.8.4.4)</li><li>点「启动」→ 等待状态变为「运行中」</li><li>点「管理后台」→ WebView 加载 One API 登录页</li><li>默认账号: <code>root</code> / <code>123456</code></li><li>局域网其他设备访问: <code>http://&lt;手机IP&gt;:3000</code></li></ol><h2 id="停止" tabindex="-1">停止 <a class="header-anchor" href="#停止" aria-label="Permalink to &quot;停止&quot;">​</a></h2><ul><li>App 内点「停止」</li><li>或杀掉 App 进程 (服务会自动停止并清理)</li></ul>`,44)])])}const u=e(s,[["render",i]]);export{b as __pageData,u as default};
